const URL='https://uqidsmtnehsjlyuxfnpa.supabase.co';
const PUBLIC_KEY='sb_publishable_Q7dRJGvD0erRMqRwzVn9bQ_FOJ1NEZW';
const OWNER='oscarcarlosalhuay@gmail.com';const APP='https://finalesmaq2026.vercel.app';
function cookies(req){return Object.fromEntries(String(req.headers.cookie||'').split(';').filter(Boolean).map(p=>{const i=p.indexOf('=');return [p.slice(0,i).trim(),decodeURIComponent(p.slice(i+1))]}))}
function setCookies(res,values){const prev=res.getHeader?.('Set-Cookie')||[];res.setHeader('Set-Cookie',[...(Array.isArray(prev)?prev:[prev]),...values])}
function cookie(name,value,seconds){return `${name}=${encodeURIComponent(value)}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${seconds}`}
function saveSession(res,s){if(s.access_token)setCookies(res,[cookie('maq_access',s.access_token,Number(s.expires_in)||3600),...(s.refresh_token?[cookie('maq_refresh',s.refresh_token,60*60*24*30)]:[])])}
async function api(path,{method='GET',body,token,service=true,headers={}}={}){const key=service?process.env.SUPABASE_SECRET_KEY:PUBLIC_KEY;if(!key)throw Object.assign(Error('La conexión con Supabase todavía no está configurada.'),{status:503});const h={apikey:key,'Content-Type':'application/json',...headers};if(token)h.Authorization='Bearer '+token;else if(service)h.Authorization='Bearer '+key;const r=await fetch(URL+path,{method,headers:h,body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(15000)});const raw=await r.text();let data;try{data=raw?JSON.parse(raw):null}catch{data=null}if(!r.ok){const e=Error(data?.msg||data?.message||data?.error_description||'No se pudo consultar Supabase.');e.status=r.status;e.code=data?.code||data?.error_code;throw e}return data}
async function profile(user){let rows=await api('/rest/v1/maq_profiles?id=eq.'+user.id+'&select=id,email,full_name,role,created_at');if(!rows?.length){const role=user.email_confirmed_at&&String(user.email).toLowerCase()===OWNER?'admin':'student';rows=await api('/rest/v1/maq_profiles?on_conflict=id',{method:'POST',body:{id:user.id,email:user.email,full_name:String(user.user_metadata?.full_name||'').slice(0,100),role},headers:{Prefer:'resolution=merge-duplicates,return=representation'}})}return rows[0]}
async function requireUser(req,res){let c=cookies(req),user=null,access=c.maq_access;if(access){try{user=await api('/auth/v1/user',{token:access,service:false})}catch(e){if(e.status!==401&&e.status!==403)throw e}}if(!user&&c.maq_refresh){try{const session=await api('/auth/v1/token?grant_type=refresh_token',{method:'POST',service:false,body:{refresh_token:c.maq_refresh}});saveSession(res,session);access=session.access_token;user=session.user}catch(e){if(e.status!==400&&e.status!==401&&e.status!==403)throw e}}if(!user)throw Object.assign(Error('Ingresá a tu cuenta para guardar y consultar tu progreso.'),{status:401});return {user,access,profile:await profile(user)}}
function guard(req,res){res.setHeader('Cache-Control','no-store');if(req.headers.origin){try{if(new global.URL(req.headers.origin).host!==req.headers.host)throw Error()}catch{throw Object.assign(Error('Origen no permitido.'),{status:403})}}}
function error(res,e){const known={email_address_not_authorized:'El envío de confirmaciones por correo todavía necesita configuración. Ingresá con Google o pedí al administrador que cree tu cuenta.',email_address_invalid:'El proveedor de correo no acepta esa dirección. Probá con Google o solicitá un alta al administrador.',invalid_credentials:'Correo o contraseña incorrectos.',email_not_confirmed:'Confirmá tu correo antes de ingresar.',user_already_exists:'Ya existe una cuenta con ese correo.',over_email_send_rate_limit:'Esperá unos minutos antes de solicitar otro correo.',weak_password:'Usá una contraseña de al menos 8 caracteres.'};return res.status(e.status>=400&&e.status<500?e.status:503).json({error:known[e.code]||e.message||'No se pudo completar la operación.'})}
async function progress(userId,subject='termicas'){return api('/rest/v1/rpc/maq_get_subject_progress',{method:'POST',body:{p_user_id:userId,p_subject:subject}})}
async function session(id,userId){const rows=await api('/rest/v1/maq_exam_sessions?id=eq.'+id+'&user_id=eq.'+userId+'&select=*');return rows?.[0]}
async function sessionAttempts(id,userId){return api('/rest/v1/maq_attempts?session_id=eq.'+id+'&user_id=eq.'+userId+'&select=question_id,topic,score,correct,hint_used,feedback,omissions,response_text&order=created_at.asc')}
function questionStats(p,id){return p?.questions?.find(q=>q.question_id===id)||{question_id:id,attempts:0,average:0,best:0,accuracy:0}}
module.exports={URL,PUBLIC_KEY,OWNER,APP,api,cookies,cookie,setCookies,saveSession,requireUser,guard,error,progress,session,sessionAttempts,questionStats};
